import{_ as a,c as t,o,af as s}from"./chunks/framework.J4isc1KJ.js";const u=JSON.parse('{"title":"组件库设计方案","description":"","frontmatter":{},"headers":[],"relativePath":"guide/design.md","filePath":"guide/design.md"}'),d={name:"guide/design.md"};function l(i,e,n,r,c,p){return o(),t("div",null,e[0]||(e[0]=[s(`<h1 id="组件库设计方案" tabindex="-1">组件库设计方案 <a class="header-anchor" href="#组件库设计方案" aria-label="Permalink to &quot;组件库设计方案&quot;">​</a></h1><p>SilenceUI 是一套面向后台管理系统的 Web Components 组件库，基于 <a href="https://lit.dev" target="_blank" rel="noreferrer">Lit 3</a> 构建，可在 Vue、React、原生 HTML 等任意宿主环境中使用。</p><h2 id="设计目标" tabindex="-1">设计目标 <a class="header-anchor" href="#设计目标" aria-label="Permalink to &quot;设计目标&quot;">​</a></h2><ol><li><strong>框架无关</strong>：产出标准 Custom Elements，一次编写，Vue / React / 原生均可直接消费。</li><li><strong>后台场景优先</strong>：组件清单围绕「增删改查 + 布局 + 反馈」的后台典型需求裁剪，不追求大而全。</li><li><strong>主题可定制</strong>：所有颜色经由 CSS 变量（design token）流转，支持一键明暗切换与运行时换肤。</li><li><strong>轻量</strong>：仅依赖 Lit（约 5KB gzip 运行时），无其他运行时依赖。</li></ol><h2 id="技术选型" tabindex="-1">技术选型 <a class="header-anchor" href="#技术选型" aria-label="Permalink to &quot;技术选型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>事项</th><th>选择</th><th>理由</th></tr></thead><tbody><tr><td>组件模型</td><td>Lit 3 + 装饰器</td><td>响应式属性、Shadow DOM 样式隔离、模板高效更新</td></tr><tr><td>样式方案</td><td>Shadow DOM 内 <code>static styles</code> + 全局 CSS 变量</td><td>隔离宿主样式污染，token 从外部穿透实现主题化</td></tr><tr><td>构建</td><td>Vite（ES / CJS / UMD 三产物）+ vite-plugin-dts</td><td>类型声明齐全，兼容各种引入方式</td></tr><tr><td>测试</td><td>Vitest + jsdom + Testing Library</td><td>与 Vite 共享配置</td></tr><tr><td>文档</td><td>VitePress</td><td>Markdown 驱动，支持组件演示</td></tr></tbody></table><h2 id="目录结构" tabindex="-1">目录结构 <a class="header-anchor" href="#目录结构" aria-label="Permalink to &quot;目录结构&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>components/</span></span>
<span class="line"><span>  _shared/           # 共享样式（baseControlStyles、focusRingStyles）与工具（parseJsonArray）</span></span>
<span class="line"><span>  form/              # 表单：select、switch、textarea、checkbox、radio-group、input-number、form-item</span></span>
<span class="line"><span>  data/              # 数据展示：card、stat-card、tag、badge、avatar、empty、skeleton、descriptions</span></span>
<span class="line"><span>  navigation/        # 导航：menu、breadcrumb、tabs、dropdown、steps</span></span>
<span class="line"><span>  feedback/          # 反馈：modal、drawer、alert、message、tooltip、spin、progress</span></span>
<span class="line"><span>  layout/            # 布局：container、divider、theme-toggle</span></span>
<span class="line"><span>  button/ input/ table/ pagination/ image/ line/ asset-viewer/   # 历史目录，保持兼容</span></span>
<span class="line"><span>styles/theme.css     # 全局 design token（唯一颜色来源）</span></span>
<span class="line"><span>utils/theme.ts       # 主题管理器（模式切换、自定义色、持久化）</span></span></code></pre></div><h2 id="命名与-api-规范" tabindex="-1">命名与 API 规范 <a class="header-anchor" href="#命名与-api-规范" aria-label="Permalink to &quot;命名与 API 规范&quot;">​</a></h2><h3 id="标签名" tabindex="-1">标签名 <a class="header-anchor" href="#标签名" aria-label="Permalink to &quot;标签名&quot;">​</a></h3><ul><li>新组件统一使用 <code>su-</code> 前缀（如 <code>su-button</code>、<code>su-modal</code>）。</li><li><code>se-table</code>、<code>se-pagination</code>、<code>se-image</code> 等为历史前缀，保持兼容不改名。</li></ul><h3 id="属性-props" tabindex="-1">属性（Props） <a class="header-anchor" href="#属性-props" aria-label="Permalink to &quot;属性（Props）&quot;">​</a></h3><ul><li>简单值（string / number / boolean）用 attribute 传递，<code>camelCase</code> 属性对应 <code>camelcase</code> 或 <code>kebab-case</code> attribute。</li><li>复杂值（数组 / 对象 / 函数）通过 property 赋值（<code>.items=\${...}</code> 或 <code>el.items = [...]</code>）。</li><li>列表型数据同时提供 <code>xxxJson</code> 字符串 attribute 作为纯 HTML 场景的降级方案，内部经 <code>parseJsonArray</code> 安全解析。</li><li>布尔属性默认 <code>false</code>，与 HTML attribute 语义一致。</li></ul><h3 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h3><ul><li>统一使用 <code>CustomEvent</code>，负载放 <code>detail</code>，并设置 <code>bubbles: true, composed: true</code> 让事件穿出 Shadow DOM。</li><li>命名使用小写单词或 kebab-case：<code>change</code>、<code>close</code>、<code>select</code>、<code>sort-change</code>、<code>load-more</code>。</li><li>全局事件挂在 <code>window</code> 上并加 <code>su-</code> 前缀，如 <code>su-theme-change</code>。</li></ul><h3 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h3><ul><li>主内容用默认插槽；结构性区域用具名插槽（<code>header</code> / <code>footer</code> / <code>sider</code>）。</li><li>动态面板（如 tabs）用「slot 名对应数据 key」的约定。</li></ul><h2 id="主题系统" tabindex="-1">主题系统 <a class="header-anchor" href="#主题系统" aria-label="Permalink to &quot;主题系统&quot;">​</a></h2><h3 id="token-分层" tabindex="-1">Token 分层 <a class="header-anchor" href="#token-分层" aria-label="Permalink to &quot;Token 分层&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>颜色语义层  --su-color-primary / success / warning / error / info</span></span>
<span class="line"><span>衍生层      --su-color-*-rgb（浅色背景、聚焦光圈）</span></span>
<span class="line"><span>            --su-color-*-contrast（叠加文字色，按 YIQ 亮度自动计算）</span></span>
<span class="line"><span>            --su-color-primary-hover（自动压暗 15%）</span></span>
<span class="line"><span>中性色层    --su-text-1/2/3、--su-bg-page/card/hover/muted、--su-border-color、--su-overlay</span></span>
<span class="line"><span>规格层      --su-radius-*、--su-font-size-*、--su-shadow-*</span></span></code></pre></div><p><strong>规则：组件样式内禁止写死颜色值，必须引用 token。</strong> 这是运行时换肤能全局生效的前提。</p><h3 id="运行时切换" tabindex="-1">运行时切换 <a class="header-anchor" href="#运行时切换" aria-label="Permalink to &quot;运行时切换&quot;">​</a></h3><ul><li>明暗模式：在 <code>&lt;html&gt;</code> 上切换 <code>data-su-theme</code> 属性（兼容 <code>.su-theme-dark</code> 类），<code>utils/theme.ts</code> 提供 <code>setThemeMode</code> / <code>toggleThemeMode</code>，状态持久化到 localStorage。</li><li>自定义颜色：<code>setThemeColors({ primary: &#39;#7c3aed&#39; })</code> 在根元素写入 CSS 变量，并自动派生 hover 色、rgb 三元组与对比文字色。</li><li><code>su-theme-toggle</code> 组件提供开箱即用的一键切换按钮，多实例通过 <code>su-theme-change</code> 事件同步。</li></ul><h2 id="无障碍-a11y" tabindex="-1">无障碍（a11y） <a class="header-anchor" href="#无障碍-a11y" aria-label="Permalink to &quot;无障碍（a11y）&quot;">​</a></h2><ul><li>交互元素使用原生 <code>button</code> / <code>input</code> / <code>select</code>，天然获得键盘与焦点行为。</li><li>弹层类组件（modal / drawer）标注 <code>role=&quot;dialog&quot;</code> + <code>aria-modal</code>，支持 Escape 关闭。</li><li>状态类组件标注 <code>role=&quot;alert&quot; / &quot;status&quot; / &quot;progressbar&quot;</code> 等语义角色。</li><li>共享的 <code>focusRingStyles</code> 提供统一的 <code>:focus-visible</code> 焦点环。</li></ul><h2 id="测试与质量" tabindex="-1">测试与质量 <a class="header-anchor" href="#测试与质量" aria-label="Permalink to &quot;测试与质量&quot;">​</a></h2><ul><li>单元测试放在组件目录内（<code>*.test.ts</code>），用 Vitest + jsdom 断言渲染结果与事件行为。</li><li>新组件的验收基线：默认渲染、属性响应、事件触发三类用例。</li></ul><h2 id="路线图" tabindex="-1">路线图 <a class="header-anchor" href="#路线图" aria-label="Permalink to &quot;路线图&quot;">​</a></h2><ul><li>[ ] date-picker / upload（后台表单高频，复杂度高，优先级最高）</li><li>[ ] notification（右上角通知，复用 message 的容器机制）</li><li>[ ] popconfirm（危险操作二次确认）</li><li>[ ] tree / cascader（组织架构、分类选择）</li><li>[ ] 表格列固定、列宽拖拽</li><li>[ ] 按需引入（每组件独立入口）</li></ul>`,29)]))}const b=a(d,[["render",l]]);export{u as __pageData,b as default};
